const text=v=>String(v==null?'':v).trim(),arr=v=>Array.isArray(v)?v:[],clone=v=>JSON.parse(JSON.stringify(v)),now=()=>new Date().toISOString(),uniq=(xs,key=x=>x)=>[...new Map(arr(xs).filter(Boolean).map(x=>[key(x),x])).values()];
