function limit(doc,id,message){if(message){const w=workflow(getClient(doc,id));if(!w.limits.includes(message))w.limits.push(message);w.limits=w.limits.slice(-40)}return doc}
async function request(url,body,timeout=58000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal}),data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.detail||data.error?.message||data.error||`HTTP ${r.status}`);return data}finally{clearTimeout(timer)}}
function searchSources(data){const out=arr(data?.output),calls=out.filter(x=>x.type==='web_search_call'),messages=out.filter(x=>x.type==='message'),a=calls.flatMap(x=>arr(x.action?.sources)),b=messages.flatMap(x=>arr(x.content)).flatMap(x=>arr(x.annotations)).filter(x=>x.url);return uniq([...a,...b].filter(x=>x?.url).map(x=>({url:x.url,title:text(x.title)})),x=>x.url)}
function rootHost(value){try{const h=new URL(value).hostname.toLowerCase().replace(/^www\./,''),p=h.split('.'),tail=p.slice(-2).join('.');return p.length<3?h:/^(com|net|org|edu|gov)\.eg$/.test(tail)?p.slice(-3).join('.'):tail}catch{return''}}
