function compactCandidates(T,items,client){const words=text(client.identity.displayName).toLowerCase().split(/\s+/).filter(x=>x.length>2),groups=new Map(),rejected=[];for(const item of items){if(!item?.url)continue;if(!T.isAccountCandidate(item.url,item.title)){rejected.push(item);continue}const platform=T.platformForURL(item.url),hay=`${item.title||''} ${item.url}`.toLowerCase(),score=words.reduce((n,w)=>n+(hay.includes(w)?2:0),0)+(/official|رسمي|الرسمية/i.test(hay)?3:0);if(!groups.has(platform))groups.set(platform,[]);groups.get(platform).push({...item,_score:score})}const eligible=[...groups.values()].flatMap(g=>g.sort((a,b)=>b._score-a._score).slice(0,3).map(({_score,...x})=>x));return[...eligible,...rejected.slice(0,20)]}
function linkedCandidates(T,source,result){const host=rootHost(source.url);return arr(result.links).map(x=>typeof x==='string'?{url:x,title:''}:{url:x.url||x.href,title:x.label||x.text||''}).filter(x=>x.url&&T.isAccountCandidate(x.url,x.title)&&rootHost(x.url)!==host).map(x=>({...x,query:`رابط متصل من ${source.platform}`}))}
