function sourceCatalog(client,T){const out=client.sources.filter(s=>s.identity?.status==='confirmed'&&s.read?.status==='read'&&text(s.content?.text)&&!badTemplatePath(s.url)&&(!T||T.sourceAnalysisEligible(s))).map(s=>({id:s.id,platform:s.platform,url:s.url,title:s.read?.title||s.platform,text:text(s.content.text).slice(0,5200),observedAt:s.read?.observedAt||null,limitations:arr(s.read?.limitations),scope:{platform:s.platform,root:rootHost(s.url),pageType:s.discovery?.internalResearch?'internal_research':'primary'}}));return uniq(out,x=>x.url).sort((a,b)=>Number(b.scope.pageType==='primary')-Number(a.scope.pageType==='primary')).slice(0,16)}
function factCatalog(client){return client.facts.filter(f=>f.review?.status!=='rejected').map(f=>({id:f.id,field:f.field,scope:f.scope||'client',value:f.review?.teamCorrection?.value||f.displayValue||f.observedValue,origin:f.review?.teamCorrection?'team_correction':'validated_source',evidence:arr(f.evidenceIds).map(id=>client.evidence.find(e=>e.id===id)).filter(Boolean).map(e=>({sourceId:e.sourceId,url:e.url,quote:e.quote,observedAt:e.observedAt||null}))})).slice(0,120)}
