async function competitors(T,doc,clientId,hooks){let next=doc,c=getClient(next,clientId),service=text(c.identity.specialty)||'الخدمة',region=clientRegion(c),query=`${service}${region?' في '+region:''}`;try{const data=await request('/api/search',{input:`ابحث عن منافسين مباشرين لـ ${query}. استخدم مصادر رسمية أو خرائط أو حسابات فقط. لا تستخدم عنوان العميل كإثبات للسوق، ولا تسم محتوى منشورًا إعلانًا من غير سجل مكتبة إعلانات.`,max_output_tokens:2200}),items=searchSources(data).filter(x=>!c.sources.some(s=>T.accountKey(s.url)===T.accountKey(x.url))).slice(0,10),rows=[];for(const item of items){if(rows.length>=4)break;try{const r=await request('/api/read',{url:item.url});if(r.status==='read'&&text(r.text).length>140)rows.push({id:`comp_${T.hash(item.url)}`,name:item.title||new URL(item.url).hostname,url:item.url,text:text(r.text).slice(0,3600),sourceType:'published_content',status:'read',observedAt:now()})}catch{}}c=getClient(next,clientId);c.integratedCompetitors={service,region:region||'',rows,adsStatus:'unverified',limits:[!region?'السوق المستهدف لم يحدده العميل؛ العنوان لم يُستخدم كبديل.':'','مكتبات الإعلانات لم تُقرأ؛ حالة الإعلان غير متحققة.'].filter(Boolean),updatedAt:now()};return await persist(hooks,next,{step:'competitors',count:rows.length})}catch(error){c=getClient(next,clientId);c.integratedCompetitors={service,region,rows:[],adsStatus:'unverified',limits:[`تعذر بحث المنافسين: ${error.message}`],updatedAt:now()};return await persist(hooks,next,{step:'competitors_failed',error:error.message})}}
function stripFence(v){return text(v).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')}
function localContentDate(value){const raw=digits(value),m=raw.match(/(?:19|20)\d{2}[-\/.]\d{1,2}[-\/.]\d{1,2}|\d{1,2}[-\/.]\d{1,2}[-\/.](?:19|20)\d{2}/);if(!m)return'';const bits=m[0].split(/[-\/.]/).map(Number);let y,mo,d;if(String(bits[0]).length===4)[y,mo,d]=bits;else[d,mo,y]=bits;const dt=new Date(Date.UTC(y,mo-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===mo-1&&dt.getUTCDate()===d?dt.toISOString().slice(0,10):''}
