async function sampleClientContent(T,doc,clientId,hooks){let next=doc,c=getClient(next,clientId);for(const source of c.sources.filter(s=>s.identity?.status==='confirmed'&&arr(T.SOCIAL_PLATFORMS).includes(s.platform)&&s.read?.status==='read'&&text(s.content?.text))){const existing=arr(c.contentSamples).find(x=>x.sourceId===source.id);if(existing?.posts?.length)continue;const posts=datedPostsFromSource(source);if(!posts.length)continue;next=T.setContentSample(next,clientId,source.id,posts,{origin:'auto_read',coverageLabel:'آخر فترة نشاط مؤرخة ظهرت في المصدر المقروء'});c=getClient(next,clientId);next=await persist(hooks,next,{step:'content_sample',sourceId:source.id,count:posts.length})}return next}
